  openGraph: {
    type: "website",
    locale: "ru_RU",
    url: "/",
    siteName: "Кварта",
    title: "Кварта — свежая обжарка кофе каждый четверг",
    description:
      "Обжарка по четвергам, развоз по пятницам. Кофе в зёрнах и дрип-пакеты из мастерской на ул. Короля, 9 в Минске.",
